private readonly environment: NodeJS.ProcessEnv;
constructor(private readonly options: ClaudeHarnessOptions = {}) {
  this.binary =
    options.binary ??
    join(
      options.env?.USERPROFILE ?? process.env.USERPROFILE ?? homedir(),
      '.local',
      'bin',
      'claude.exe',
    );
